anchor.body:
  priceCents: row.eventOccurrence?.event?.priceCents ?? row.payment?.priceCents,
  onlineCheckoutAvailable: true,
  paymentRequired: row.eventOccurrence?.event?.paymentRequired ?? null,
  occurrenceStatus: row.eventOccurrence?.status ?? null,
  paymentHoldExpiresAt: row.payment?.paymentHoldExpiresAt,
}).payable;

if (input.paymentStatus === "not_required" || input.paymentRequired === false) {
  return blocked("manual_settlement");
}

if (input.bookingStatus !== "confirmed") {
  return blocked("booking_not_confirmed");
}

if (input.occurrenceStatus != null && input.occurrenceStatus !== "scheduled") {
  return blocked("occurrence_not_available");
}

if (input.paymentHoldExpiresAt != null) {
  return blocked("checkout_in_flight");
}

// `jsonError` shape: { error: <message>, code, details } — see respond.ts.
const payload = (await response.json().catch(() => ({}))) as {
  checkoutUrl?: string;
  error?: string;
  code?: string;
};
if (!response.ok || !payload.checkoutUrl) {
  // #452: the server now says WHY. The button is only rendered on rows the
  // shared eligibility contract cleared, so reaching this at all means the
  // page is stale (the instructor marked it paid, cancelled the term,
  // switched Connect off) — name the state instead of the old blanket
  // "online payment is not available right now", which left a customer
  // with a debt and no next step.
  notifications.show({
    title: t('finances.payOnlineUnavailable'),
    message: mapBookingErrorCode(payload.code, locale, '', payload.error),
    color: 'orange',
  });
  setLoading(false);
  return;
}

  const { booking } = await readConsole(customer.userId, customer.email, bookingId);
  expect(booking?.payment?.payable).toBe(false);
  expect(booking?.payment?.payableBlocker).toBe("occurrence_not_available");
});

/**
 * Booking statuses on which an unpaid booking counts as outstanding/payable.
 * Shared by the Finances tab overview and the Bookings tab pay button so the
 * two surfaces can never drift apart.
 */
export const PAYABLE_BOOKING_STATUSES: ReadonlySet<string> = new Set([
  "confirmed",
  "attended",
  "no_show",
]);

import { redirect } from 'next/navigation';
import { loadAccountSettingsContext } from '@/application/account/loadAccountSettingsContext';
import { AccountSettingsView } from '@/presentation/components/account/AccountSettingsView';

export default async function AccountPage({
  params,
}: {
  params: Promise<{ locale: string }>;
}) {
  const { locale } = await params;

  let context;
  try {
    context = await loadAccountSettingsContext(locale);
  } catch {
    redirect(`/${locale}/login`);
  }

  return <AccountSettingsView context={context} />;
}
